mapper.select:
SELECT project_id, COUNT(DISTINCT user_id) AS member_count FROM project_member WHERE project_id IN
#{id}
GROUP BY project_id

SELECT ranked.project_id, ranked.user_id, su.display_name
FROM (
    SELECT project_id, user_id, ROW_NUMBER() OVER (
        PARTITION BY project_id ORDER BY MIN(joined_at)
    ) AS rn
    FROM project_member
    WHERE project_id IN

        #{id}

    GROUP BY project_id, user_id
) ranked
JOIN sys_user su ON su.id = ranked.user_id
WHERE ranked.rn <= #{topN}
ORDER BY ranked.project_id, ranked.rn
